// ALL start rules live here. Change thresholds here, not in Python.
// Plug state comes from Victron EV charger /Status, not the Tesla cache, so a
// sleeping car does not block a start. The start command wakes the car.
// Starts as often as needed while plugged in (solar goes up and down), with a
// pause between attempts so wakes/commands stay cheap. "Rearm/pause after
// failed start" lengthens the pause when a start fails.
const BATTERY_ONLY_SOC = 50;   // strictly above
const SOLAR_MIN_SOC = 20;      // at least
const SOLAR_WATTS = 700;      // strictly above
const ATTEMPT_PAUSE_SECONDS = 30 * 60;
const MIN_CHARGE_LIMIT = 80;    // the start command raises a lower limit to this
const STATUS_NAMES = {0: "Disconnected", 1: "Connected", 2: "Charging", 3: "Charged"};
const now = Date.now() / 1000;
function wait(reason) {
    node.status({fill: "grey", shape: "ring", text: reason});
    return null;
}
const input = msg.payload || {};
const state = input.session === null || input.session === undefined ? {} : input.session;
if (!state || typeof state !== "object" || Array.isArray(state)) {
    node.error("Invalid saved session state; no start sent", msg);
    return null;
}
const p = flow.get("teslaEnergy") || {};
if (p.EVChargerStatus == null || p.EVChargerStatus === "") return wait("Missing charger status");
const status = Number(p.EVChargerStatus);
msg.startRequested = false;
if (status === 0) {
    // Unplugged: drop any pause so a new plug-in can start right away.
    if (JSON.stringify(state) === "{}") return wait("Unplugged");
    node.status({fill: "grey", shape: "ring", text: "Unplugged: pause cleared"});
    msg.payload = "{}";
    msg.expectedState = msg.payload;
    return msg;
}
// A car that is full at a limit below 80% still gets a start: the command raises the limit.
const limitTooLow = Number.isFinite(input.charge_limit) && input.charge_limit < MIN_CHARGE_LIMIT;
if (status === 2 || (status === 3 && !limitTooLow)) {
    node.status({fill: "green", shape: "dot", text: STATUS_NAMES[status]});
    return null;
}
if (status !== 1 && status !== 3) return wait("Charger status " + status + "; not starting");
if (typeof state.retry_after === "number" && now < state.retry_after) {
    return wait((state.reason || "Paused") + "; next try " + new Date(state.retry_after * 1000).toLocaleTimeString());
}
if (p.BatterySOC == null || p.PVPower == null || p.BatterySOC === "" || p.PVPower === "") return wait("Missing house readings");
const soc = Number(p.BatterySOC), solar = Number(p.PVPower);
if (!Number.isFinite(soc) || soc < 0 || soc > 100 || !Number.isFinite(solar) || solar < 0) return wait("Invalid house readings");
if (!(soc > BATTERY_ONLY_SOC || (soc >= SOLAR_MIN_SOC && solar > SOLAR_WATTS))) return wait("Waiting for battery or solar");
msg.payload = JSON.stringify({attempted_at: now, retry_after: now + ATTEMPT_PAUSE_SECONDS, reason: "Started recently"});
msg.expectedState = msg.payload;
msg.startRequested = true;
node.status({fill: "yellow", shape: "dot", text: "Saving attempt before start"});
return msg;

// Runs on any stderr from the start command, i.e. a failed start.
// Car said "disconnected" (Victron status was stale): try again in 30 min.
// Car still asleep after the helper's 2-minute wake wait: also 30 min.
// Car too slow to answer (command timed out): try again in 10 min.
// Car said it is full (driver has not reported Charged yet): 10 min.
// Any other failure (token, quota, ...): 30 min, the same as between normal attempts.
// Output 1 saves the pause; output 2 appends the error to auto-start-errors.log.
const UNPLUGGED_PAUSE_SECONDS = 30 * 60;
const TIMEOUT_PAUSE_SECONDS = 10 * 60;
const OTHER_FAILURE_PAUSE_SECONDS = 30 * 60;
const err = String(msg.payload || "").trim();
if (!err) return null;
const unplugged = /could not execute command: disconnected/i.test(err);
const asleep = /offline or asleep/i.test(err);
const timedOut = /timed out|deadline exceeded/i.test(err);
const full = /could not execute command: complete/i.test(err);
const now = Date.now() / 1000;
const pause = unplugged || asleep ? UNPLUGGED_PAUSE_SECONDS : timedOut || full ? TIMEOUT_PAUSE_SECONDS : OTHER_FAILURE_PAUSE_SECONDS;
const retryAfter = now + pause;
const reason = unplugged ? "Car said unplugged" : asleep ? "Car did not wake" : timedOut ? "Car timed out" : full ? "Car is full" : "Start failed";
msg.payload = JSON.stringify({attempted_at: now, retry_after: retryAfter, reason: reason});
node.status({fill: "yellow", shape: "ring", text: reason + "; next try " + new Date(retryAfter * 1000).toLocaleTimeString()});
const logLine = {payload: new Date(now * 1000).toISOString() + " " + reason + ": " + err.replace(/\s+/g, " ").slice(0, 1000)};
return [msg, logLine];
